package ru.mirea.autosalon.api.controller;
import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.http.ResponseEntity;
import ru.mirea.autosalon.api.domain.*; import ru.mirea.autosalon.api.dto.AutosalonDtos.*; import ru.mirea.autosalon.api.dto.PageResponse; import ru.mirea.autosalon.api.error.*; import ru.mirea.autosalon.api.filter.RequestFilters; import ru.mirea.autosalon.api.repository.*; import ru.mirea.autosalon.api.service.*;
import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@io.swagger.v3.oas.annotations.security.SecurityRequirement(name="bearerAuth")
@RestController @RequestMapping("/api") public class AutosalonController {
 private final AutosalonService service; private final CarRepository cars; private final ClientRepository clients; private final RequestNoteRepository notes; private final ru.mirea.autosalon.api.security.CurrentUserService current; private final AuditService audit;
 public AutosalonController(AutosalonService s,CarRepository c,ClientRepository l,RequestNoteRepository n,ru.mirea.autosalon.api.security.CurrentUserService u,AuditService a){service=s;cars=c;clients=l;notes=n;current=u;audit=a;}
 private Pageable page(int page,int size,String sort){if(page<0||size<1||size>100)throw new BadRequestException("Недопустимая страница или размер (1–100)");String[] parts=sort.split(",",2);String field=Map.of("scheduledAt","scheduledAt","duration","durationMinutes","status","status","client","client.fullName","car","car.brand","createdAt","createdAt","externalId","externalId").get(parts[0]);if(field==null)throw new BadRequestException("Недопустимое поле сортировки");return PageRequest.of(page,size,Sort.by(parts.length>1&&parts[1].equalsIgnoreCase("desc")?Sort.Direction.DESC:Sort.Direction.ASC,field));}
 @GetMapping("/requests") public PageResponse<RequestView> search(@RequestParam(defaultValue="") String q,@RequestParam(required=false) UUID carId,@RequestParam(required=false) RequestStatus status,@RequestParam(required=false) Boolean callback,@RequestParam(required=false) RequestPriority priority,@RequestParam(required=false) String tag,@RequestParam(defaultValue="false") String archived,@RequestParam(required=false) Integer durationMin,@RequestParam(required=false) Integer durationMax,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="25") int size,@RequestParam(defaultValue="scheduledAt,asc") String sort){Boolean archive=switch(archived){case "all"->null;case "true"->true;case "false"->false;default->throw new BadRequestException("archived: true, false или all");};return PageResponse.from(service.search(new RequestFilters.Filter(q,carId,status,callback,priority,tag,archive,durationMin,durationMax),page(page,size,sort)));}
 @GetMapping("/requests/{id}") public RequestView get(@PathVariable UUID id){return service.get(id);}
 @PostMapping("/requests") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") public ResponseEntity<RequestView> create(@Valid @RequestBody RequestInput in){return ResponseEntity.status(201).body(service.create(in));}
 @PutMapping("/requests/{id}") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") public RequestView update(@PathVariable UUID id,@Valid @RequestBody RequestInput in){return service.update(id,in);}
 @DeleteMapping("/requests/{id}") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") public RequestView archive(@PathVariable UUID id){return service.archive(id,true);}
 @PostMapping("/requests/{id}/restore") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") public RequestView restore(@PathVariable UUID id){return service.archive(id,false);}
 @DeleteMapping("/requests/{id}/permanent") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> permanent(@PathVariable UUID id){service.permanent(id);return ResponseEntity.noContent().build();}
 @GetMapping("/analytics/summary") public Analytics analytics(){return service.analytics();}
 @GetMapping("/cars") @Transactional(readOnly=true) public List<CarView> cars(@RequestParam(defaultValue="false") boolean activeOnly){return cars.findAllByOrderByBrandAscModelAsc().stream().filter(c->!activeOnly||c.active).map(AutosalonController::carView).toList();}
 @PostMapping("/cars") @PreAuthorize("hasRole('ADMIN')") @Transactional public CarView createCar(@Valid @RequestBody CarInput in){Car c=new Car();applyCar(c,in);cars.saveAndFlush(c);audit.record("CAR_CREATED","CAR",c.publicId,"Добавлен автомобиль",Map.of());return carView(c);}
 @PutMapping("/cars/{id}") @PreAuthorize("hasRole('ADMIN')") @Transactional public CarView updateCar(@PathVariable UUID id,@Valid @RequestBody CarInput in){Car c=cars.findByPublicId(id).orElseThrow(()->new NotFoundException("Автомобиль не найден"));if(in.version()==null||in.version()!=c.version)throw new ConflictException("Автомобиль изменён");applyCar(c,in);cars.flush();audit.record("CAR_UPDATED","CAR",id,"Изменён автомобиль",Map.of());return carView(c);}
 private void applyCar(Car c,CarInput i){c.brand=i.brand().strip();c.model=i.model().strip();c.manufactureYear=i.manufactureYear();c.vin=i.vin();c.color=i.color().strip();c.price=i.price();c.status=i.status();c.active=i.active();}
 private static CarView carView(Car c){return new CarView(c.publicId,c.brand,c.model,c.manufactureYear,c.vin,c.color,c.price,c.status,c.active,c.version);}
 @GetMapping("/clients") @Transactional(readOnly=true) public List<ClientView> clients(){return clients.findAllByOrderByFullNameAsc().stream().map(AutosalonController::clientView).toList();}
 @PostMapping("/clients") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") @Transactional public ClientView createClient(@Valid @RequestBody ClientInput i){if(i.birthDate().plusYears(18).isAfter(LocalDate.now()))throw new BadRequestException("Клиент должен быть старше 18 лет");Client c=new Client();c.fullName=i.fullName().strip();c.phone=i.phone();c.email=i.email();c.birthDate=i.birthDate();c.licenseNumber=i.licenseNumber();clients.saveAndFlush(c);audit.record("CLIENT_CREATED","CLIENT",c.publicId,"Добавлен клиент",Map.of());return clientView(c);}
 private static ClientView clientView(Client c){return new ClientView(c.publicId,c.fullName,c.phone,c.email,c.birthDate,c.licenseNumber);}
 @GetMapping("/requests/{id}/notes") @Transactional(readOnly=true) public List<NoteView> notes(@PathVariable UUID id){service.require(id);return notes.findAllByRequestPublicIdOrderByPinnedDescCreatedAtDesc(id).stream().map(this::noteView).toList();}
 @PostMapping("/requests/{id}/notes") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") @Transactional public NoteView addNote(@PathVariable UUID id,@Valid @RequestBody NoteInput i){RequestNote n=new RequestNote();n.id=UUID.randomUUID();n.request=service.require(id);n.author=current.requireEntity();n.body=i.body().strip();n.pinned=i.pinned();n=notes.saveAndFlush(n);audit.record("NOTE_CREATED","REQUEST",id,"Добавлена заметка",Map.of());return noteView(n);}
 @PutMapping("/requests/{id}/notes/{noteId}") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") @Transactional public NoteView updateNote(@PathVariable UUID id,@PathVariable UUID noteId,@Valid @RequestBody NoteInput i){RequestNote n=note(id,noteId);if(i.version()==null||i.version()!=n.getVersion())throw new ConflictException("Заметка изменена");n.body=i.body().strip();n.pinned=i.pinned();notes.flush();audit.record("NOTE_UPDATED","REQUEST",id,"Изменена заметка",Map.of());return noteView(n);}
 @DeleteMapping("/requests/{id}/notes/{noteId}") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") @Transactional public ResponseEntity<Void> deleteNote(@PathVariable UUID id,@PathVariable UUID noteId){notes.delete(note(id,noteId));audit.record("NOTE_DELETED","REQUEST",id,"Удалена заметка",Map.of());return ResponseEntity.noContent().build();}
 private RequestNote note(UUID id,UUID nid){return notes.findByIdAndRequestPublicId(nid,id).orElseThrow(()->new NotFoundException("Заметка не найдена"));}
 private NoteView noteView(RequestNote n){return new NoteView(n.id,n.author.getDisplayName(),n.body,n.pinned,n.getCreatedAt(),n.getUpdatedAt(),n.getVersion());}
 @PostMapping("/requests/bulk") @PreAuthorize("hasAnyRole('MANAGER','ADMIN')") public BulkResult bulk(@Valid @RequestBody BulkInput in){List<BulkFailure> failures=new ArrayList<>();int ok=0;for(UUID id:in.ids()){try{RequestView r=service.get(id);switch(in.action()){case ARCHIVE->service.archive(id,true);case RESTORE->service.archive(id,false);case SET_STATUS,ADD_TAG,REMOVE_TAG->{Set<String> tags=new LinkedHashSet<>(r.tags());if(in.action()==BulkAction.ADD_TAG||in.action()==BulkAction.REMOVE_TAG){if(in.tag()==null||in.tag().isBlank())throw new BadRequestException("Тег обязателен");if(in.action()==BulkAction.ADD_TAG)tags.add(in.tag().strip());else tags.remove(in.tag().strip().toLowerCase(Locale.ROOT));}RequestStatus status=in.action()==BulkAction.SET_STATUS?in.status():r.status();if(status==null)throw new BadRequestException("Статус обязателен");service.update(id,new RequestInput(r.externalId(),r.clientId(),r.carId(),r.scheduledAt(),r.durationMinutes(),status,r.comment(),r.callbackRequested(),tags,r.version()));}}ok++;}catch(RuntimeException ex){failures.add(new BulkFailure(id,(ex instanceof BadRequestException || ex instanceof ConflictException || ex instanceof NotFoundException) ? ex.getMessage() : "Не удалось выполнить операцию"));}}return new BulkResult(in.ids().size(),ok,failures);}
}